curl --fail-with-body -X POST https://openaliment.ro/api/v2/program/assets \
  -H 'Accept: application/json' \
  -H 'Authorization: Bearer YOUR_ACCESS_TOKEN' \
  -H 'Content-Type: application/json' \
  --data '{"purpose":"avatar","content_base64":"Exemplu sintetic","rights_confirmed":true}'
```

### JavaScript

```javascript
