  "type": "object",
  "properties": {
    "items": {
      "type": "array",
      "items": {
        "$ref": "#/components/schemas/ProgramEvent"
      },
      "maxItems": 100,
      "description": "Elementele colecției, în forma și ordinea declarate de operație."
    },
    "next_cursor": {
      "anyOf": [
        {
          "type": "string",
          "pattern": "^[a-f0-9]{32}$"
        },
        {
          "type": "null"
        }
      ],
      "description": "ID-ul exclusiv pentru pagina următoare; null la final. Nu este un offset numeric."
    },
    "has_more": {
      "type": "boolean",
      "description": "Există o pagină următoare; continuă cu cursorul corespunzător și aceleași filtre."
    },
    "limit": {
      "type": "integer",
      "minimum": 1,
      "maximum": 100,
      "description": "Mărimea paginii aplicată de server; nu numărul total al înregistrărilor."
    }
  },
  "required": [
    "items",
    "next_cursor",
    "has_more",
    "limit"
  ],
  "additionalProperties": false,
  "description": "Structura ProgramPageEvent. Exemplele sunt sintetice; permisiunile și stările reale se verifică la cerere."
}
```

